--DS d_ds_script_inv_mast_tradeSELECT 'INVTRAXDET' invtraxdef,inv_mast.item_id,inv_mast_trade.inv_mast_uid, inv_mast_trade.company_id,inv_mast_trade.trade_type_cd, part_type_trade.trade_type, part_type_trade.trade_type_desc, inv_mast_trade.broker_description, inv_mast_trade.import_uom, inv_mast_trade.import_tariff_amount, inv_mast_trade.export_tariff_amount, inv_mast_trade.added_value, inv_mast_trade.nafta_class, inv_mast_trade.import_tariff_number, inv_mast_trade.export_tariff_number, inv_mast_trade.scrap_tariff_number, inv_mast_trade.lacey_intended_use, inv_mast_trade.schedule_b_number, inv_mast_trade.hts_classification, inv_mast_trade.tax_class, inv_mast_trade.harmonized_tax, inv_mast_trade.preference_criterion, inv_mast_trade.producer_flag, inv_mast_trade.net_cost_flag FROM inv_mast_trade	INNER JOIN inv_mast ON inv_mast.inv_mast_uid = inv_mast_trade.inv_mast_uidINNER JOIN company ON company.company_id = inv_mast_trade.company_idLEFT JOIN company_trade ON company_trade.company_id = company.company_id LEFT JOIN part_type_trade ON part_type_trade.part_type_trade_uid = inv_mast_trade.part_type_trade_uidWHERE company_trade.use_nafta_flag = 'Y' AND inv_mast_trade.company_id = '1' AND inv_mast.item_id in ('689-2RSA1CNHANGU225%','3021363000','3021364000','3021850000REVA','3021850000REVA','689-2RSA1CNHANGU225%','3021363000','3021364000')